// pubspec.yaml:
//   firebase_core: ^2.24.0
//   firebase_auth: ^4.15.0
//   google_sign_in: ^6.2.0
//   sign_in_with_apple: ^5.0.0

import 'package:firebase_auth/firebase_auth.dart';
import 'package:google_sign_in/google_sign_in.dart';
import 'package:sign_in_with_apple/sign_in_with_apple.dart';

final auth = FirebaseAuth.instance;

// ────── Reactive auth state ──────
StreamBuilder<User?>(
  stream: auth.authStateChanges(),
  builder: (context, snapshot) {
    if (snapshot.connectionState == ConnectionState.waiting) return const CircularProgressIndicator();
    final user = snapshot.data;
    return user == null ? const LoginScreen() : HomeScreen(user: user);
  },
);

// authStateChanges — fires on sign-in / sign-out.
// userChanges       — also fires on profile update.
// idTokenChanges    — fires when the JWT itself changes (every hour on refresh).

// ────── Email/password ──────
try {
  final cred = await auth.createUserWithEmailAndPassword(email: e, password: p);
  await cred.user!.sendEmailVerification();
  await cred.user!.updateDisplayName('Ada Lovelace');
} on FirebaseAuthException catch (ex) {
  // 'weak-password' | 'email-already-in-use' | 'invalid-email'
}

await auth.signInWithEmailAndPassword(email: e, password: p);
await auth.sendPasswordResetEmail(email: e);
await auth.signOut();

// ────── Google Sign-In ──────
Future<UserCredential> signInWithGoogle() async {
  final googleUser = await GoogleSignIn().signIn();
  final googleAuth = await googleUser!.authentication;
  final credential = GoogleAuthProvider.credential(
    accessToken: googleAuth.accessToken,
    idToken: googleAuth.idToken,
  );
  return auth.signInWithCredential(credential);
}

// ────── Apple Sign-In ──────
Future<UserCredential> signInWithApple() async {
  final appleCred = await SignInWithApple.getAppleIDCredential(
    scopes: [AppleIDAuthorizationScopes.email, AppleIDAuthorizationScopes.fullName],
  );
  final oauthCred = OAuthProvider('apple.com').credential(
    idToken: appleCred.identityToken,
    accessToken: appleCred.authorizationCode,
  );
  return auth.signInWithCredential(oauthCred);
}

// ────── Phone OTP ──────
await auth.verifyPhoneNumber(
  phoneNumber: '+911234567890',
  verificationCompleted: (cred) async => await auth.signInWithCredential(cred),
  verificationFailed: (e) => print('failed: ${e.message}'),
  codeSent: (verificationId, resendToken) async {
    // Show OTP entry screen; user types code:
    final smsCode = await promptUser();
    final cred = PhoneAuthProvider.credential(verificationId: verificationId, smsCode: smsCode);
    await auth.signInWithCredential(cred);
  },
  codeAutoRetrievalTimeout: (_) {},
);

// ────── Anonymous → upgrade to permanent ──────
await auth.signInAnonymously();
// ... user browses as guest, decides to sign up ...
final emailCred = EmailAuthProvider.credential(email: e, password: p);
await auth.currentUser!.linkWithCredential(emailCred);
// Now same UID owns their guest data + is permanently signed up.

// ────── ID token for your backend ──────
final idToken = await auth.currentUser?.getIdToken();
// POST to your API with `Authorization: Bearer $idToken`.
// Your backend verifies via Firebase Admin SDK: admin.auth().verifyIdToken(token).

// Node.js Cloud Function — set custom claims (RUNS ON SERVER, admin privileges).
const admin = require('firebase-admin');

exports.makeUserAdmin = functions.https.onCall(async (data, context) => {
  if (!context.auth || context.auth.token.role !== 'super-admin') {
    throw new functions.https.HttpsError('permission-denied', 'Only super-admins can set roles');
  }
  await admin.auth().setCustomUserClaims(data.uid, {
    role: 'admin',
    tenantId: data.tenantId,
    plan: 'gold',
  });
  return { success: true };
});

// On the CLIENT, after claims change on server:
await auth.currentUser!.getIdToken(true);  // force refresh; claims now in the new token
// Or wait ~1 hour — token auto-refresh will pick them up.

